yakit.AutoInitYakit()
// 获取越权与未授权响应长度，受到yakit结果展示限制，需要根据URL找到数据包自行发送请求获取结果进行确认
# Input your code!



// 获取用户输入的头部信息
header = cli.Text("header", cli.setVerboseName("key"), cli.setRequired(true), cli.setHelp("输入鉴权的key，多个字段按行分割"),cli.setDefault("Cookie:123"))
cli.check()
headerKeyAndValue = header.Split("\n")


// 创建输出表格
yakit.EnableTable("结果输出",["URL","原始长度","越权长度","未授权长度"])

// 获取头部信息
headerMap = make(map[string]string)
for i = range len(headerKeyAndValue) {
    headers = headerKeyAndValue[i].Split(":")
    headerMap.Set(headers[0], headers[1])
}


// 处理未授权请求
func unAuth(req) {
    headKey = headerMap.Keys()
    for i in headKey {
        try{
            req = poc.DeleteHTTPPacketHeader(req, i /*type: string*/)
        } catch err {
            yakit.Info("删除请求头失败")
        }
        
    }
    return req
}

// 处理越权请求
func exAuth(req) {
    headerMap.ForEach(func(k, v){
        req = poc.ReplaceHTTPPacketHeader(req, k /*type: string*/, v)
    })
    return req
}

// 存放响应长度
unAuthLen = ""
exAuthLen= ""

// 获取数据
yakitFlow = yakit.QueryHTTPFlowsAll()
// 用来存放响应长度数组
respLenList = []
for flow in yakitFlow{
    // 响应数组
    respList = []
    if flow['FromPlugin'] == false && !str.Contains(flow['Url'], ".js"){
        OriLen = len(string(flow.GetResponse()))    // 获取响应原始长度
        respList.Append(flow["Url"], OriLen) // 添加URL和原始长度到数组中
        req = flow.GetRequest() // 获取请求结构体
        yakit.Info(f"正在测试地址：${flow['Url']}")
        exAuthRsp = ""
        unAuthRsp = ""
        HttpsStatus = flow["IsHTTPS"]
        try{
            unAuthRsp,unAuthReq = poc.HTTP(unAuth(req),poc.https(HttpsStatus))~    // 发送未授权请求
            
            if len(string(unAuthRsp)) == OriLen {
                unAuthLen = len(string(unAuthRsp)) + "，疑似存在未授权"
            } else {
                unAuthLen = len(string(unAuthRsp))
            }

        } catch err{
            yakit.Info(f`未授权请求${flow["Url"]}发送失败`)
        }
        try{
            exAuthRsp,exAuthReq = poc.HTTP(exAuth(req),poc.https(HttpsStatus))~    // 发送越权请求
            if len(string(exAuthRsp)) == OriLen {
                exAuthLen = len(string(exAuthRsp)) + "，疑似存在越权"
            } else {
                exAuthLen = len(string(exAuthRsp))
            }

        } catch err {
            yakit.Info(f"越权请求${flow["Url"]}}发送失败")
            println(err)
        }
        respList.Append(exAuthLen, unAuthLen)
        respLenList.Append(respList)
    }
}



// 结果展示
for i in respLenList{
    data = make(map[string]var)
    data["URL"] = i[0]
    data["原始长度"] = i[1]
    data["越权长度"] = i[2]
    data['未授权长度'] = i[3]
    yakit.Output(yakit.TableData("结果输出", data))
}
